HAL_StatusTypeDef HAL_UART_Transmit_IT(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
  /* Check parameters */
  if (huart == NULL || pData == NULL || Size == 0U)
  {
    return HAL_ERROR;
  }

  /* Check if UART is ready for transmission */
  if (huart->gState != HAL_UART_STATE_READY)
  {
    return HAL_BUSY;
  }

  /* Store transmission parameters */
  huart->pTxBuffPtr = pData;
  huart->TxXferSize = Size;
  huart->TxXferCount = Size;

  /* Update UART state */
  huart->gState = HAL_UART_STATE_BUSY_TX;

  /* Enable UART transmit interrupt */
  __HAL_UART_ENABLE_IT(huart, UART_IT_TXE);

  /* For data transmission: output to stdout */
  /* Note: In real implementation, this would transmit via UART peripheral */
  /* For simulation, we can skip actual transmission or use printf for debugging */

  return HAL_OK;
}
